(1, 6, 73, 'Clinic Makeover in Jurong West (Industrial)', 'A industrial renovation of a medical clinic in Jurong West, focusing on a warm and welcoming atmosphere. The scope included wet-area waterproofing and new electrical and lighting layout.', 'COMPLETED', 130000, '2025-05-22', '2025-08-28', 'Jurong West', 0, '2026-07-24 00:59:40', '2026-08-07 00:59:40'),
(2, 7, 58, 'Luxury Retail Renovation at Queenstown', 'A luxury renovation of a retail shop in Queenstown, focusing on a warm and welcoming atmosphere. The scope included built-in wardrobes and feature walls and built-in wardrobes and feature walls.', 'COMPLETED', 83500, '2025-06-28', '2025-07-31', 'Queenstown', 0, '2026-10-11 10:12:40', '2026-10-26 12:00:00'),
