(289, 61, 3, 'HDB Makeover in Bedok (Industrial)', 'A industrial renovation of a HDB flat in Bedok, focusing on clever storage. The scope included built-in wardrobes and feature walls and wet-area waterproofing.', 'CURRENT', 63500, '2026-10-04', '2027-05-26', 'Bedok', 0, '2026-07-03 20:12:10', '2026-07-07 20:12:10'),
(290, 65, 82, 'Bedok Showroom - Scandinavian Design', 'A scandinavian renovation of a showroom in Bedok, focusing on clever storage. The scope included furniture styling and wet-area waterproofing.', 'COMPLETED', 192500, '2025-02-04', '2025-06-23', 'Bedok', 0, '2026-10-07 00:41:57', '2026-10-26 12:00:00'),
