(1, 25, 221, 'I would like to know what is included in the budget shown for this project. We are renovating a office space.', 'NEW', '2026-10-03 05:18:21', '2026-10-03 05:18:21', NULL, NULL),
(2, 136, 198, 'Could you tell me the typical timeline for a project like this? Thank you.', 'READ', '2026-10-12 19:00:12', '2026-10-13 19:00:12', '2026-10-13 19:00:12', NULL),
